//! macOS: salida del texto y app con foco. Hermana de las partes Win32 de `inject.rs`.
//!
//! - Portapapeles: `NSPasteboard` general. Se guarda TODO lo que había (cada elemento con cada uno de
//!   sus tipos) y se devuelve igual, como en Windows. Lo que pone Pronto lleva las marcas
//!   `org.nspasteboard.TransientType` y `AutoGeneratedType` (convención de nspasteboard.org que
//!   respetan los gestores de portapapeles: no lo guardan en su historial; regla 1).
//! - Teclas: `CGEventPost` en el nivel HID, con la marca `MARKER` en `EventSourceUserData` para que
//!   nuestro propio gancho las ignore, y los modificadores puestos a mano en cada evento (así una Fn
//!   aún pulsada no convierte Cmd+V en Fn+Cmd+V). Pide el permiso de Accesibilidad.
//! - App con foco: `NSWorkspace.frontmostApplication`; el título de su ventana, por Accesibilidad
//!   (`AXFocusedWindow` → `AXTitle`), con un plazo corto por si la app no responde.

use crate::inject::{AppInfo, KeyEvent, MARKER};
use crate::teclas_mac::{flags_for, mac_from_vk, modifier_bits};
use objc2::rc::{autoreleasepool, Retained};
use objc2::runtime::ProtocolObject;
use objc2_app_kit::{NSApplicationActivationOptions, NSPasteboard, NSPasteboardItem, NSPasteboardWriting, NSRunningApplication, NSWorkspace};
use objc2_application_services::{AXError, AXUIElement};
use objc2_core_foundation::{CFRetained, CFString, CFType};
use objc2_core_graphics::{CGEvent, CGEventField, CGEventFlags, CGEventSource, CGEventSourceStateID, CGEventTapLocation};
use objc2_foundation::{NSArray, NSData, NSString};
use std::ptr::NonNull;
use std::sync::atomic::{AtomicI32, Ordering};
use std::time::{Duration, Instant};

/// Contenido del portapapeles: cada elemento con sus tipos (UTI) y los bytes de cada uno.
pub type Clip = Vec<Vec<(String, Vec<u8>)>>;

const TEXT_TYPE: &str = "public.utf8-plain-text";
/// Marcas de nspasteboard.org: «no lo guardes en el historial» y «lo puso un programa».
const MARKS: [&str; 2] = ["org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType"];

/// Última app (pid) que tenía el foco cuando empezó un dictado, sin contar Pronto.
static LAST_TARGET: AtomicI32 = AtomicI32::new(0);

fn own_pid() -> i32 {
    std::process::id() as i32
}

// ------------------------------------------------------------------ portapapeles

/// Todo lo que hay en el portapapeles (`None` si no se pudo leer: entonces no se restaura nada).
pub(crate) fn read_clipboard() -> Option<Clip> {
    autoreleasepool(|_| {
        let pb = NSPasteboard::generalPasteboard();
        let Some(items) = pb.pasteboardItems() else { return Some(Vec::new()) };
        let mut clip: Clip = Vec::new();
        for item in items.iter() {
            let mut entry = Vec::new();
            for ty in item.types().iter() {
                if let Some(data) = item.dataForType(&ty) {
                    entry.push((ty.to_string(), data.to_vec()));
                }
            }
            if !entry.is_empty() {
                clip.push(entry);
            }
        }
        Some(clip)
    })
}

/// Sustituye el portapapeles por `clip` (vacío = lo deja vacío). Devuelve los tipos que no entraron.
pub(crate) fn write_clipboard(clip: &Clip) -> Result<Vec<String>, String> {
    autoreleasepool(|_| {
        let pb = NSPasteboard::generalPasteboard();
        pb.clearContents();
        if clip.is_empty() {
            return Ok(Vec::new());
        }
        let mut failed = Vec::new();
        let mut objects: Vec<Retained<ProtocolObject<dyn NSPasteboardWriting>>> = Vec::new();
        for entry in clip {
            let item = NSPasteboardItem::new();
            for (ty, bytes) in entry {
                let data = NSData::with_bytes(bytes);
                if !item.setData_forType(&data, &NSString::from_str(ty)) {
                    failed.push(ty.clone());
                }
            }
            objects.push(ProtocolObject::from_retained(item));
        }
        let array = NSArray::from_retained_slice(&objects);
        if pb.writeObjects(&array) { Ok(failed) } else { Err("macOS no aceptó el contenido del portapapeles".into()) }
    })
}

/// Pone el texto de Pronto con sus marcas «no lo guardes en el historial». Un NUL dentro del texto
/// se quita, como en Windows.
pub(crate) fn write_text(text: &str) -> Result<(), String> {
    let clean: String = text.chars().filter(|&c| c != '\0').collect();
    let mut entry = vec![(TEXT_TYPE.to_string(), clean.into_bytes())];
    entry.extend(MARKS.iter().map(|m| (m.to_string(), Vec::new())));
    let failed = write_clipboard(&vec![entry])?;
    if failed.iter().any(|t| t == TEXT_TYPE) {
        return Err("no se pudo escribir el texto".into());
    }
    if !failed.is_empty() {
        eprintln!("[inject] marcas del portapapeles que no entraron: {failed:?}");
    }
    Ok(())
}

/// Número que cambia cada vez que alguien escribe en el portapapeles (`changeCount`).
pub(crate) fn clipboard_seq() -> u32 {
    autoreleasepool(|_| NSPasteboard::generalPasteboard().changeCount() as u32)
}

// ------------------------------------------------------------------ teclas

/// ¿Está pulsada esta tecla (código virtual de Windows)? Para esperar a que se suelten los modificadores.
pub(crate) fn key_down(vk: u32) -> bool {
    crate::mac::hotkey::async_down(vk)
}

/// Espera (hasta `max`) a que se suelte la Fn: si no, algunas apps reciben Fn+Cmd+V.
fn wait_fn_released(max: Duration) {
    let t0 = Instant::now();
    while crate::mac::hotkey::fn_down() && t0.elapsed() < max {
        std::thread::sleep(Duration::from_millis(10));
    }
}

/// Inyecta eventos marcados como propios, en orden. Los códigos son los virtuales de Windows
/// (`0x5B` = Cmd, `0x56` = V…), traducidos con `teclas_mac`.
pub fn send_key_events(keys: &[KeyEvent]) {
    // Sin Accesibilidad, macOS descarta las teclas sin avisar: se apunta (el dictado ya está en el historial).
    // SAFETY: sin precondiciones.
    if !unsafe { objc2_application_services::AXIsProcessTrusted() } {
        crate::errlog::error("inject", "falta el permiso de Accesibilidad: macOS no deja pulsar teclas por ti");
    }
    wait_fn_released(Duration::from_millis(600));
    let source = CGEventSource::new(CGEventSourceStateID::Private);
    let mut held: Vec<u32> = Vec::new();
    for k in keys {
        let vk = k.vk as u32;
        let Some(code) = mac_from_vk(vk) else {
            eprintln!("[inject] tecla sin equivalente en Mac: {vk:#X}");
            continue;
        };
        if modifier_bits(code).is_some() {
            if k.up {
                held.retain(|v| *v != vk);
            } else if !held.contains(&vk) {
                held.push(vk);
            }
        }
        let Some(ev) = CGEvent::new_keyboard_event(source.as_deref(), code, !k.up) else {
            crate::errlog::error("inject", "macOS no creó el evento de teclado");
            continue;
        };
        CGEvent::set_flags(Some(&ev), CGEventFlags(flags_for(&held)));
        CGEvent::set_integer_value_field(Some(&ev), CGEventField::EventSourceUserData, MARKER as i64);
        CGEvent::post(CGEventTapLocation::HIDEventTap, Some(&ev));
        // Un respiro entre eventos: algunas apps (Electron) pierden la V si llega pegada al Cmd.
        std::thread::sleep(Duration::from_millis(4));
    }
}

/// Inyecta una secuencia de teclas `(vk, soltar)` marcadas como propias.
pub fn send_keys(keys: &[(u16, bool)]) {
    let events: Vec<KeyEvent> = keys.iter().map(|&(vk, up)| KeyEvent::vk(vk, up)).collect();
    send_key_events(&events);
}

// ------------------------------------------------------------------ app con foco

/// Nombre «de ejecutable» que entiende `text::category_for_app` (igual que en Windows sin `.exe`).
/// Las apps cuyo ejecutable se llama distinto en Mac se traducen por su identificador.
fn canonical_exe(bundle_id: &str, executable: &str) -> String {
    match bundle_id {
        "us.zoom.xos" => "Zoom".into(),
        "com.microsoft.teams2" | "com.microsoft.teams" => "Teams".into(),
        "com.microsoft.Outlook" => "Outlook".into(),
        "com.apple.mail" => "Mail".into(),
        "net.whatsapp.WhatsApp" | "desktop.WhatsApp" => "WhatsApp".into(),
        "ru.keepcoder.Telegram" | "org.telegram.desktop" => "Telegram".into(),
        _ => executable.to_string(),
    }
}

fn info_of(app: &NSRunningApplication) -> AppInfo {
    let bundle = app.bundleIdentifier().map(|s| s.to_string()).unwrap_or_default();
    let executable = app
        .executableURL()
        .and_then(|u| u.lastPathComponent())
        .map(|s| s.to_string())
        .or_else(|| app.localizedName().map(|s| s.to_string()))
        .unwrap_or_default();
    let pid = app.processIdentifier();
    AppInfo { exe: canonical_exe(&bundle, &executable), title: window_title(pid).unwrap_or_default() }
}

/// Título de la ventana con foco de `pid`, por Accesibilidad. `None` sin permiso o si la app no responde.
fn window_title(pid: i32) -> Option<String> {
    // SAFETY: AXIsProcessTrusted no tiene precondiciones.
    if pid <= 0 || !unsafe { objc2_application_services::AXIsProcessTrusted() } {
        return None;
    }
    // SAFETY: `pid` es un proceso; el elemento se suelta solo (CFRetained).
    let app = unsafe { AXUIElement::new_application(pid) };
    // Una app colgada no debe colgar el dictado: 150 ms como mucho por pregunta.
    // SAFETY: elemento válido.
    let _ = unsafe { app.set_messaging_timeout(0.15) };
    let window = ax_attribute(&app, "AXFocusedWindow")?.downcast::<AXUIElement>().ok()?;
    // SAFETY: elemento válido. El plazo corto también para la ventana.
    let _ = unsafe { window.set_messaging_timeout(0.15) };
    let title = ax_attribute(&window, "AXTitle")?.downcast::<CFString>().ok()?;
    Some(title.to_string())
}

fn ax_attribute(el: &AXUIElement, name: &str) -> Option<CFRetained<CFType>> {
    let mut value: *const CFType = std::ptr::null();
    // SAFETY: `value` es un puntero válido a un puntero; si la llamada va bien, nos da una referencia
    // propia (+1) que pasa a ser del CFRetained.
    let err = unsafe { el.copy_attribute_value(&CFString::from_str(name), NonNull::from(&mut value)) };
    if err != AXError::Success || value.is_null() {
        return None;
    }
    // SAFETY: referencia propia y no nula (comprobado arriba).
    Some(unsafe { CFRetained::from_raw(NonNull::new_unchecked(value as *mut CFType)) })
}

/// App y título de la ventana con foco. Nunca falla: devuelve vacíos si no puede. Recuerda la app
/// (si no es Pronto) para devolverle el foco antes de pegar.
pub fn foreground_app() -> AppInfo {
    autoreleasepool(|_| {
        let Some(app) = NSWorkspace::sharedWorkspace().frontmostApplication() else { return AppInfo::default() };
        let pid = app.processIdentifier();
        if pid > 0 && pid != own_pid() {
            LAST_TARGET.store(pid, Ordering::SeqCst);
        }
        info_of(&app)
    })
}

/// La app con foco como número (su pid; 0 = ninguna). Equivale a la ventana con foco de Windows.
pub fn foreground_window() -> isize {
    autoreleasepool(|_| NSWorkspace::sharedWorkspace().frontmostApplication().map_or(0, |a| a.processIdentifier() as isize))
}

/// App y título de una app cualquiera por su pid (vacíos si no se puede leer).
pub fn app_info_of(pid: isize) -> AppInfo {
    autoreleasepool(|_| match NSRunningApplication::runningApplicationWithProcessIdentifier(pid as i32) {
        Some(app) => info_of(&app),
        None => AppInfo::default(),
    })
}

/// Si Pronto está delante (la persona pulsó la Flow bar), devuelve el foco a la app donde empezó el
/// dictado y espera a que llegue (hasta 400 ms). Si no, no hace nada.
/// Pegar falla si falta Accesibilidad (macOS tira las teclas en silencio): así el flujo lo trata
/// como pegado fallido y avisa, con el dictado guardado (regla 5).
pub(crate) fn can_paste() -> Result<(), String> {
    // SAFETY: sin precondiciones.
    if unsafe { objc2_application_services::AXIsProcessTrusted() } { Ok(()) } else { Err("falta el permiso de Accesibilidad (Pronto → Permisos del Mac)".into()) }
}

pub(crate) fn ensure_target_front() {
    let target = LAST_TARGET.load(Ordering::SeqCst);
    if target <= 0 || foreground_window() as i32 != own_pid() {
        return;
    }
    let activated = autoreleasepool(|_| match NSRunningApplication::runningApplicationWithProcessIdentifier(target) {
        #[allow(deprecated)] // ActivateIgnoringOtherApps no hace nada desde macOS 14, pero no estorba
        Some(app) => app.activateWithOptions(NSApplicationActivationOptions::ActivateIgnoringOtherApps),
        None => false,
    });
    if !activated {
        return;
    }
    let t0 = Instant::now();
    while foreground_window() as i32 != target && t0.elapsed() < Duration::from_millis(400) {
        std::thread::sleep(Duration::from_millis(15));
    }
    // La ventana recién activada tarda un poco en aceptar teclas.
    std::thread::sleep(Duration::from_millis(60));
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn nombres_de_apps_que_entiende_la_categoria() {
        use crate::text::{category_for_app, Category};
        assert_eq!(category_for_app(&canonical_exe("com.tinyspeck.slackmacgap", "Slack"), ""), Category::Work);
        assert_eq!(category_for_app(&canonical_exe("us.zoom.xos", "zoom.us"), ""), Category::Work);
        assert_eq!(category_for_app(&canonical_exe("com.microsoft.Outlook", "Microsoft Outlook"), ""), Category::Email);
        assert_eq!(category_for_app(&canonical_exe("net.whatsapp.WhatsApp", "WhatsApp"), ""), Category::Personal);
    }
}
